export function expandCommands(input) {
  const out=[];const commands=input.trim();if(!commands)return [];
  for(const token of commands.split(/\s+/)){const m=/^([NSEW])(\d+)$/.exec(token);if(!m)throw new Error('Invalid command');const n=Number(m[2]);if(n>1000)throw new Error('Too many moves');for(let i=0;i<n;i++)out.push(m[1]);}
  return out;
}
